{
  "decisions": [
    {
      "decision": "shortage_bound_direction",
      "evidence": "\"the skill shortages for Project 0, Skill 0 must be less than or equal to -8, for Project 0, Skill 1 must be less than or equal to -8, ...\"",
      "options": [
        "shortage[j,s] <= given_negative_bound (as literally stated)",
        "shortage[j,s] >= given_negative_bound (treat as a lower bound / minimum attainment)",
        "drop the explicit bounds entirely (they are implied by the shortage definition)"
      ],
      "plausibility": [
        0.45,
        0.45,
        0.1
      ],
      "majority_option": "shortage[j,s] <= given_negative_bound (as literally stated)"
    },
    {
      "decision": "shortage_sign_convention",
      "evidence": "\"The skill shortage for each project is the difference between the required skill level and the attained skill level.\"",
      "options": [
        "shortage = required - attained (positive means deficit)",
        "shortage = attained - required (positive means surplus)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "shortage = required - attained (positive means deficit)"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"The goal is to minimize the maximum skill shortage across all projects and skills.\"",
      "options": [
        "minimize z where z >= shortage[j,s] for all (j,s)",
        "minimize z where z >= |shortage[j,s]| for all (j,s)",
        "minimize sum of shortages over all (j,s)"
      ],
      "plausibility": [
        0.85,
        0.1,
        0.05
      ],
      "majority_option": "minimize z where z >= shortage[j,s] for all (j,s)"
    },
    {
      "decision": "shortage_variable_domain",
      "evidence": "\"The skill shortage for each project is the difference between the required skill level and the attained skill level.\"",
      "options": [
        "Reals (shortage may be negative when attained exceeds required)",
        "NonNegativeReals (shortage floored at zero)",
        "NonPositiveReals (shortage is a deficit, always <= 0)"
      ],
      "plausibility": [
        0.7,
        0.2,
        0.1
      ],
      "majority_option": "Reals (shortage may be negative when attained exceeds required)"
    },
    {
      "decision": "z_variable_domain",
      "evidence": "\"minimize the maximum skill shortage across all projects and skills\"",
      "options": [
        "Reals",
        "NonNegativeReals"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "Reals"
    },
    {
      "decision": "assignment_variable_domain",
      "evidence": "\"each staff member is assigned to exactly one project\"",
      "options": [
        "Binary x[p,j] with sum_j x[p,j] == 1",
        "NonNegativeIntegers x[p,j] with sum_j x[p,j] == 1",
        "NonNegativeReals x[p,j] with sum_j x[p,j] == 1 (fractional assignment)"
      ],
      "plausibility": [
        0.9,
        0.05,
        0.05
      ],
      "majority_option": "Binary x[p,j] with sum_j x[p,j] == 1"
    }
  ]
}
